#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Record point2 := mkPoint2 { px : R; py : R }. Definition square (c : point2) (r : R) : seq point2 := [:: mkPoint2 (px c - r) (py c - r); mkPoint2 (px c + r) (py c - r); mkPoint2 (px c + r) (py c + r); mkPoint2 (px c - r) (py c + r)]. Theorem pyramid_volume_star_figure : let S_side := 40%:R in let S'_side := 15%:R in let c := mkPoint2 0 0 in let S := square c (S_side / 2) in let S' := square c (S'_side / 2) in exists volume : R, volume = (1/3) * S'_side^2 * 20%:R. Proof. Admitted.
